class ResourceStore:
    def __init__(self):
        self.users = {1: {"id": 1, "name": "Ana"}}
        self.next_id = 2

    def get(self, uid):
        return self.users.get(uid)

    def post(self, name):
        uid = self.next_id
        self.users[uid] = {"id": uid, "name": name}
        self.next_id += 1
        return self.users[uid]

    def put(self, uid, name):
        self.users[uid] = {"id": uid, "name": name}
        return self.users[uid]

    def delete(self, uid):
        self.users.pop(uid, None)
        return {"deleted": uid}


store = ResourceStore()
print("GET", store.get(1))
print("POST", store.post("Beto"))
print("POST", store.post("Beto"))
print("PUT", store.put(1, "Ana Garcia"))
print("PUT again", store.put(1, "Ana Garcia"))
print("DELETE", store.delete(2))
print("DELETE again", store.delete(2))

